"use client";

import React, { useEffect, useId, useRef, useState } from "react";
import { motion, useReducedMotion } from "framer-motion";

function cn(...classes: Array<string | false | null | undefined>): string {
  return classes.filter(Boolean).join(" ");
}

export type LiquidHomeButtonSize = "sm" | "md" | "lg";
export type LiquidHomeButtonTheme = "auto" | "dark" | "light";

export interface LiquidHomeButtonProps
  extends Omit<
    React.ButtonHTMLAttributes<HTMLButtonElement>,
    "onAnimationStart" | "onDragStart" | "onDragEnd" | "onDrag"
  > {
  /** Primary button text label */
  label?: string;
  /** Proportional size preset preserving exact concentric pill-to-orb geometry */
  size?: LiquidHomeButtonSize;
  /** Duration in seconds for one complete liquid caustic sweep cycle */
  orbitDuration?: number;
  /** Intensity multiplier (0 to 1.5) for ambient caustic bloom and prism radiance */
  glowIntensity?: number;
  /** Color theme mode: 'auto' adapts to Tailwind dark mode, or force 'dark' / 'light' */
  theme?: LiquidHomeButtonTheme;
  /** Optional custom icon replacing the default brushed-silver Home glyph */
  icon?: React.ReactNode;
  /** Enable or pause the continuous liquid chromatic sweep */
  animate?: boolean;
  /** Highlights the button as the active navigation item */
  active?: boolean;
}

const SIZE_CONFIG: Record<
  LiquidHomeButtonSize,
  {
    pill: string;
    innerBezel: string;
    orbPx: number;
    ringThickness: number;
    iconBox: string;
    label: string;
    gap: string;
  }
> = {
  sm: {
    pill: "h-12 pl-1.5 pr-6",
    innerBezel: "inset-[2.5px]",
    orbPx: 36,
    ringThickness: 3.5,
    iconBox: "h-[17px] w-[17px]",
    label: "text-[15px] tracking-[-0.015em]",
    gap: "gap-3",
  },
  md: {
    pill: "h-16 pl-2 pr-8",
    innerBezel: "inset-[3px]",
    orbPx: 48,
    ringThickness: 4.75,
    iconBox: "h-[23px] w-[23px]",
    label: "text-[20px] tracking-[-0.02em]",
    gap: "gap-4",
  },
  lg: {
    pill: "h-20 pl-2 pr-10",
    innerBezel: "inset-[4px]",
    orbPx: 64,
    ringThickness: 6.25,
    iconBox: "h-[30px] w-[30px]",
    label: "text-[26px] tracking-[-0.022em]",
    gap: "gap-5",
  },
};

function degToRad(deg: number): number {
  return (deg * Math.PI) / 180;
}

function shortestAngleDiff(a: number, b: number): number {
  let d = a - b;
  while (d > Math.PI) d -= Math.PI * 2;
  while (d < -Math.PI) d += Math.PI * 2;
  return d;
}

function gaussian(dist: number, sigma: number): number {
  const x = dist / sigma;
  return Math.exp(-0.5 * x * x);
}

/**
 * 60fps HiDPI optical liquid-prism ring canvas.
 * Reproduces the reference's oscillating studio-light caustic sweep with
 * true additive RGB wavelength dispersion, dynamic surge bloom, obsidian
 * dark troughs, and micro-fluted crystal striations.
 */
function LiquidPrismCanvas({
  orbPx,
  ringThickness,
  orbitDuration,
  glowIntensity,
  shouldAnimate,
  isHovered,
}: {
  orbPx: number;
  ringThickness: number;
  orbitDuration: number;
  glowIntensity: number;
  shouldAnimate: boolean;
  isHovered: boolean;
}) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const hoverTargetRef = useRef(0);
  const hoverCurrentRef = useRef(0);
  const durationRef = useRef(orbitDuration);
  const glowRef = useRef(glowIntensity);

  useEffect(() => {
    hoverTargetRef.current = isHovered ? 1 : 0;
  }, [isHovered]);

  useEffect(() => {
    durationRef.current = orbitDuration;
  }, [orbitDuration]);

  useEffect(() => {
    glowRef.current = glowIntensity;
  }, [glowIntensity]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const canvasCssSize = Math.round(orbPx * 1.9);
    canvas.width = Math.round(canvasCssSize * dpr);
    canvas.height = Math.round(canvasCssSize * dpr);

    const cx = canvasCssSize / 2;
    const cy = canvasCssSize / 2;
    const outerR = orbPx / 2;
    const innerR = outerR - ringThickness;
    const midR = (outerR + innerR) / 2;

    let rafId = 0;
    let startTime: number | null = null;
    const SEGMENTS = 144;
    const step = (Math.PI * 2) / SEGMENTS;

    const renderFrame = (phase: number, hoverVal: number) => {
      const glow = glowRef.current;
      ctx.save();
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, canvasCssSize, canvasCssSize);

      // Smooth C-infinity sinusoidal sweep matching the 5s reference choreography:
      // wave = 0 at moody obsidian-prism rest (t=0, 1), wave = 1 at right-side incandescent surge (t=0.5)
      const wave = 0.5 - 0.5 * Math.cos(phase * Math.PI * 2);
      const surge = Math.pow(wave, 1.45);
      const energy = Math.min(1.45, glow * (1 + hoverVal * 0.22));

      // Measured angular trajectories from the 60fps reference frames:
      // Primary caustic sweeps 246° (11:15) -> 338° (2:15) -> 246°
      const primaryAngle = degToRad(246 + 92 * wave);
      // Secondary opposite refraction sweeps 104° (6:30) -> 170° (8:40) -> 104°
      const secondaryAngle = degToRad(104 + 66 * wave);
      // Tertiary subtle right-rim refraction when primary is on left
      const tertiaryAngle = degToRad(345 - 28 * wave);

      // Angular lobe widths dynamically widen during the incandescent surge
      const primarySigma = degToRad(26 + 26 * surge);
      const secondarySigma = degToRad(24 + 10 * surge);
      const tertiarySigma = degToRad(18);

      // Chromatic dispersion angular split (R vs G vs B)
      const dispBase = degToRad(10.5 + 3.5 * (1 - surge * 0.45));

      // 1. OUTER AMBIENT CAUSTIC HALO (soft light spill onto the dark glass pill)
      if (energy > 0.02) {
        ctx.save();
        ctx.globalCompositeOperation = "screen";

        const pHaloR = outerR * (0.62 + 0.34 * surge);
        const pHaloX = cx + Math.cos(primaryAngle) * (midR + ringThickness * 0.35);
        const pHaloY = cy + Math.sin(primaryAngle) * (midR + ringThickness * 0.35);
        const pGrad = ctx.createRadialGradient(pHaloX, pHaloY, 0, pHaloX, pHaloY, pHaloR);
        const pAlpha = Math.min(0.85, (0.28 + 0.46 * surge) * energy);
        pGrad.addColorStop(0, `rgba(255, 250, 238, ${pAlpha.toFixed(3)})`);
        pGrad.addColorStop(0.35, `rgba(255, 212, 145, ${(pAlpha * 0.48).toFixed(3)})`);
        pGrad.addColorStop(0.68, `rgba(96, 178, 255, ${(pAlpha * 0.2).toFixed(3)})`);
        pGrad.addColorStop(1, "rgba(0, 0, 0, 0)");
        ctx.fillStyle = pGrad;
        ctx.beginPath();
        ctx.arc(pHaloX, pHaloY, pHaloR, 0, Math.PI * 2);
        ctx.fill();

        const sHaloR = outerR * (0.52 + 0.16 * surge);
        const sHaloX = cx + Math.cos(secondaryAngle) * (midR + ringThickness * 0.25);
        const sHaloY = cy + Math.sin(secondaryAngle) * (midR + ringThickness * 0.25);
        const sGrad = ctx.createRadialGradient(sHaloX, sHaloY, 0, sHaloX, sHaloY, sHaloR);
        const sAlpha = Math.min(0.65, (0.22 + 0.24 * surge) * energy);
        sGrad.addColorStop(0, `rgba(255, 232, 200, ${sAlpha.toFixed(3)})`);
        sGrad.addColorStop(0.4, `rgba(255, 130, 68, ${(sAlpha * 0.42).toFixed(3)})`);
        sGrad.addColorStop(0.72, `rgba(56, 189, 248, ${(sAlpha * 0.22).toFixed(3)})`);
        sGrad.addColorStop(1, "rgba(0, 0, 0, 0)");
        ctx.fillStyle = sGrad;
        ctx.beginPath();
        ctx.arc(sHaloX, sHaloY, sHaloR, 0, Math.PI * 2);
        ctx.fill();

        ctx.restore();
      }

      // 2. OBSIDIAN GLASS TORUS BASE CHANNEL (clipped to exact ring annulus)
      ctx.save();
      ctx.beginPath();
      ctx.arc(cx, cy, outerR, 0, Math.PI * 2, false);
      ctx.arc(cx, cy, innerR, 0, Math.PI * 2, true);
      ctx.clip();

      ctx.fillStyle = "#050508";
      ctx.fillRect(cx - outerR - 1, cy - outerR - 1, orbPx + 2, orbPx + 2);

      // 3. TRUE ADDITIVE RGB CHROMATIC DISPERSION ARCS
      ctx.globalCompositeOperation = "lighter";
      ctx.lineCap = "butt";

      for (let i = 0; i < SEGMENTS; i++) {
        const theta = i * step;
        const a0 = theta - step * 0.6;
        const a1 = theta + step * 0.6;

        const evalChannel = (angleOffset: number) => {
          const t = theta + angleOffset;
          const p =
            gaussian(shortestAngleDiff(t, primaryAngle), primarySigma) *
            (0.95 + 0.55 * surge);
          const s =
            gaussian(shortestAngleDiff(t, secondaryAngle), secondarySigma) *
            (0.82 + 0.22 * surge);
          const tr =
            gaussian(shortestAngleDiff(t, tertiaryAngle), tertiarySigma) *
            (0.28 * (1 - surge * 0.7));
          return Math.min(1.5, (p + s + tr) * energy);
        };

        const flute = 0.88 + 0.12 * Math.sin(theta * 46 + phase * Math.PI * 4);

        const iRed = evalChannel(-dispBase) * flute;
        const iMid = evalChannel(0) * flute;
        const iBlue = evalChannel(dispBase) * flute;

        if (iRed < 0.025 && iMid < 0.025 && iBlue < 0.025) continue;

        if (iBlue > 0.025) {
          const alpha = Math.min(1, iBlue * 0.92);
          ctx.strokeStyle = `rgba(38, 168, 255, ${alpha.toFixed(3)})`;
          ctx.lineWidth = ringThickness * 0.95;
          ctx.beginPath();
          ctx.arc(cx, cy, midR - ringThickness * 0.08, a0, a1);
          ctx.stroke();

          const indigoAlpha = Math.min(0.75, iBlue * 0.55);
          ctx.strokeStyle = `rgba(45, 78, 235, ${indigoAlpha.toFixed(3)})`;
          ctx.lineWidth = ringThickness * 1.05;
          ctx.beginPath();
          ctx.arc(cx, cy, midR, a0, a1);
          ctx.stroke();
        }

        if (iRed > 0.025) {
          const alpha = Math.min(1, iRed * 0.95);
          ctx.strokeStyle = `rgba(255, 74, 24, ${alpha.toFixed(3)})`;
          ctx.lineWidth = ringThickness * 0.95;
          ctx.beginPath();
          ctx.arc(cx, cy, midR + ringThickness * 0.08, a0, a1);
          ctx.stroke();

          const goldAlpha = Math.min(0.85, iRed * 0.65);
          ctx.strokeStyle = `rgba(255, 194, 54, ${goldAlpha.toFixed(3)})`;
          ctx.lineWidth = ringThickness * 0.72;
          ctx.beginPath();
          ctx.arc(cx, cy, midR, a0, a1);
          ctx.stroke();
        }

        if (iMid > 0.18) {
          const core = Math.pow(Math.min(1.2, (iMid - 0.14) / 0.85), 1.45);
          const coreAlpha = Math.min(1, core * (0.85 + 0.25 * surge));
          ctx.strokeStyle = `rgba(255, 254, 248, ${coreAlpha.toFixed(3)})`;
          ctx.lineWidth = ringThickness * (0.48 + 0.34 * Math.min(1, core));
          ctx.beginPath();
          ctx.arc(cx, cy, midR, a0, a1);
          ctx.stroke();
        }
      }

      // 4. CRISP OUTER & INNER GLASS TORUS BEVEL RIM
      ctx.globalCompositeOperation = "source-over";
      ctx.strokeStyle = "rgba(255, 255, 255, 0.22)";
      ctx.lineWidth = 0.9;
      ctx.beginPath();
      ctx.arc(cx, cy, outerR - 0.45, 0, Math.PI * 2);
      ctx.stroke();

      ctx.strokeStyle = "rgba(0, 0, 0, 0.72)";
      ctx.lineWidth = 1.1;
      ctx.beginPath();
      ctx.arc(cx, cy, innerR + 0.45, 0, Math.PI * 2);
      ctx.stroke();

      ctx.restore();

      // 5. SYNCHRONIZED INTERNAL DISC EDGE SHEEN (paints softly over smoked glass, beneath Home icon)
      if (energy > 0.05) {
        ctx.save();
        ctx.beginPath();
        ctx.arc(cx, cy, innerR - 0.5, 0, Math.PI * 2);
        ctx.clip();
        ctx.globalCompositeOperation = "screen";

        const bleedX = cx + Math.cos(primaryAngle) * (innerR * 0.88);
        const bleedY = cy + Math.sin(primaryAngle) * (innerR * 0.88);
        const bleedR = innerR * (0.95 + 0.35 * surge);
        const bleedGrad = ctx.createRadialGradient(bleedX, bleedY, 0, bleedX, bleedY, bleedR);
        const bAlpha = Math.min(0.42, (0.11 + 0.24 * surge) * energy);
        bleedGrad.addColorStop(0, `rgba(255, 250, 235, ${bAlpha.toFixed(3)})`);
        bleedGrad.addColorStop(0.5, `rgba(210, 224, 245, ${(bAlpha * 0.35).toFixed(3)})`);
        bleedGrad.addColorStop(1, "rgba(0, 0, 0, 0)");
        ctx.fillStyle = bleedGrad;
        ctx.fillRect(cx - innerR, cy - innerR, innerR * 2, innerR * 2);

        ctx.restore();
      }

      ctx.restore();
    };

    if (!shouldAnimate) {
      renderFrame(0.14, hoverTargetRef.current);
      return;
    }

    const tick = (now: number) => {
      if (startTime === null) startTime = now;
      const elapsedSec = (now - startTime) / 1000;
      const dur = Math.max(1.2, durationRef.current);
      const phase = (elapsedSec / dur) % 1;

      hoverCurrentRef.current +=
        (hoverTargetRef.current - hoverCurrentRef.current) * 0.08;

      renderFrame(phase, hoverCurrentRef.current);
      rafId = window.requestAnimationFrame(tick);
    };

    rafId = window.requestAnimationFrame(tick);
    return () => {
      window.cancelAnimationFrame(rafId);
    };
  }, [orbPx, ringThickness, shouldAnimate]);

  const canvasCssSize = Math.round(orbPx * 1.9);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden="true"
      className="pointer-events-none absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2"
      style={{
        width: `${canvasCssSize}px`,
        height: `${canvasCssSize}px`,
      }}
    />
  );
}

function DefaultHomeGlyph({
  uid,
  isLightOnly,
  isDarkOnly,
  className,
}: {
  uid: string;
  isLightOnly: boolean;
  isDarkOnly: boolean;
  className?: string;
}) {
  const darkGradId = `${uid}-home-metal-dark`;
  const lightGradId = `${uid}-home-metal-light`;

  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      aria-hidden="true"
      className={cn(
        "transition-transform duration-300 ease-out group-hover/liquid-btn:scale-[1.04]",
        className
      )}
      style={{
        filter: isLightOnly
          ? "drop-shadow(0 1.5px 3px rgba(15, 23, 42, 0.22))"
          : "drop-shadow(0 3px 6px rgba(0, 0, 0, 0.52))",
      }}
    >
      <defs>
        <linearGradient
          id={darkGradId}
          x1="4"
          y1="3"
          x2="20"
          y2="21"
          gradientUnits="userSpaceOnUse"
        >
