export const LiquidHomeButton = React.forwardRef<
  HTMLButtonElement,
  LiquidHomeButtonProps
>(function LiquidHomeButton(
  {
    label = "Home",
    size = "md",
    orbitDuration = 5,
    glowIntensity = 1,
    theme = "auto",
    icon,
    animate = true,
    active = false,
    disabled = false,
    className,
    type = "button",
    onMouseEnter,
    onMouseLeave,
    ...props
  },
  ref
) {
  const rawId = useId();
  const uid = rawId.replace(/:/g, "");
  const prefersReducedMotion = useReducedMotion();
  const [isHovered, setIsHovered] = useState(false);

  const safeSize: LiquidHomeButtonSize =
    size === "sm" || size === "md" || size === "lg" ? size : "md";
  const safeTheme: LiquidHomeButtonTheme =
    theme === "auto" || theme === "dark" || theme === "light" ? theme : "auto";
  const safeDuration =
    typeof orbitDuration === "number" && Number.isFinite(orbitDuration)
      ? Math.min(20, Math.max(1.2, orbitDuration))
      : 5;
  const safeGlow =
    typeof glowIntensity === "number" && Number.isFinite(glowIntensity)
      ? Math.min(1.5, Math.max(0, glowIntensity))
      : 1;

  const dims = SIZE_CONFIG[safeSize];
  const shouldAnimate = animate && !prefersReducedMotion && !disabled;
  const isDarkOnly = safeTheme === "dark";
  const isLightOnly = safeTheme === "light";

  const innerDiscSize = dims.orbPx - dims.ringThickness * 2;

  const outerShellClasses = isDarkOnly
    ? cn(
        "bg-[#121214] shadow-[0_14px_34px_-10px_rgba(0,0,0,0.88),inset_0_1px_0_rgba(255,255,255,0.11),inset_0_-1px_0_rgba(255,255,255,0.03)]",
        active ? "border-white/25" : "border-white/[0.11]"
      )
    : isLightOnly
      ? cn(
          "bg-white/85 shadow-[0_12px_28px_-10px_rgba(15,23,42,0.18),inset_0_1px_0_rgba(255,255,255,0.95),inset_0_-1px_0_rgba(15,23,42,0.05)]",
          active ? "border-slate-900/25" : "border-slate-900/[0.11]"
        )
      : cn(
          "bg-white/85 dark:bg-[#121214] shadow-[0_12px_28px_-10px_rgba(15,23,42,0.18),inset_0_1px_0_rgba(255,255,255,0.95),inset_0_-1px_0_rgba(15,23,42,0.05)] dark:shadow-[0_14px_34px_-10px_rgba(0,0,0,0.88),inset_0_1px_0_rgba(255,255,255,0.11),inset_0_-1px_0_rgba(255,255,255,0.03)]",
          active
            ? "border-slate-900/25 dark:border-white/25"
            : "border-slate-900/[0.11] dark:border-white/[0.11]"
        );

  const innerBezelClasses = isDarkOnly
    ? "bg-gradient-to-b from-[#1e1d1f] via-[#18181a] to-[#141416] border-white/[0.08] shadow-[inset_0_1px_1px_rgba(255,255,255,0.08),inset_0_-1px_2px_rgba(0,0,0,0.7)]"
    : isLightOnly
      ? "bg-gradient-to-b from-[#fafbfc] via-[#f1f4f8] to-[#e6ebf2] border-slate-900/[0.07] shadow-[inset_0_1px_1px_rgba(255,255,255,0.9),inset_0_-1px_2px_rgba(15,23,42,0.06)]"
      : "bg-gradient-to-b from-[#fafbfc] via-[#f1f4f8] to-[#e6ebf2] dark:from-[#1e1d1f] dark:via-[#18181a] dark:to-[#141416] border-slate-900/[0.07] dark:border-white/[0.08] shadow-[inset_0_1px_1px_rgba(255,255,255,0.9),inset_0_-1px_2px_rgba(15,23,42,0.06)] dark:shadow-[inset_0_1px_1px_rgba(255,255,255,0.08),inset_0_-1px_2px_rgba(0,0,0,0.7)]";

  const innerDiscClasses = isDarkOnly
    ? "bg-[radial-gradient(circle_at_48%_32%,#3c3c42_0%,#2a2a2f_58%,#1e1e22_100%)] border-white/[0.16] shadow-[inset_0_1px_2px_rgba(255,255,255,0.2),inset_0_-3px_7px_rgba(0,0,0,0.72)]"
    : isLightOnly
      ? "bg-[radial-gradient(circle_at_48%_32%,#ffffff_0%,#eef2f6_58%,#dce3ec_100%)] border-white/95 shadow-[inset_0_1px_2px_rgba(255,255,255,1),inset_0_-2px_5px_rgba(15,23,42,0.12)]"
      : "bg-[radial-gradient(circle_at_48%_32%,#ffffff_0%,#eef2f6_58%,#dce3ec_100%)] dark:bg-[radial-gradient(circle_at_48%_32%,#3c3c42_0%,#2a2a2f_58%,#1e1e22_100%)] border-white/95 dark:border-white/[0.16] shadow-[inset_0_1px_2px_rgba(255,255,255,1),inset_0_-2px_5px_rgba(15,23,42,0.12)] dark:shadow-[inset_0_1px_2px_rgba(255,255,255,0.2),inset_0_-3px_7px_rgba(0,0,0,0.72)]";

  const labelColorClasses = isDarkOnly
    ? "text-[#FFFFFF]"
    : isLightOnly
      ? "text-slate-900"
      : "text-slate-900 dark:text-[#FFFFFF]";

  return (
    <motion.button
      ref={ref}
      type={type}
      disabled={disabled}
      aria-pressed={active || undefined}
      onMouseEnter={(e) => {
        setIsHovered(true);
        onMouseEnter?.(e);
      }}
      onMouseLeave={(e) => {
        setIsHovered(false);
        onMouseLeave?.(e);
      }}
      whileHover={
        disabled || prefersReducedMotion
          ? undefined
          : { y: -1, transition: { type: "spring", stiffness: 420, damping: 28 } }
      }
      whileTap={
        disabled || prefersReducedMotion
          ? undefined
          : { scale: 0.975, transition: { type: "spring", stiffness: 500, damping: 30 } }
      }
      className={cn(
        "group/liquid-btn relative inline-flex select-none items-center rounded-full border backdrop-blur-xl transition-colors duration-200",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400/75 focus-visible:ring-offset-2 focus-visible:ring-offset-transparent",
        disabled ? "cursor-not-allowed opacity-55" : "cursor-pointer",
        dims.pill,
        dims.gap,
        outerShellClasses,
        className
      )}
      style={{
        fontFamily:
          '"Plus Jakarta Sans", "Inter", -apple-system, BlinkMacSystemFont, sans-serif',
      }}
      {...props}
    >
      {/* Inner recessed double-bezel glass housing */}
      <span
        aria-hidden="true"
        className={cn(
          "pointer-events-none absolute rounded-full border transition-opacity duration-300",
          dims.innerBezel,
          innerBezelClasses
        )}
      />

      {/* Crisp 1px top-edge glass specular highlight across the pill */}
      <span
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-8 top-[1px] h-[1px] rounded-full bg-gradient-to-r from-transparent via-white/25 to-transparent opacity-80"
      />

      {/* Concentric Circular Liquid Chromatic Prism Medallion */}
      <span
        className="relative z-10 flex shrink-0 items-center justify-center rounded-full"
        style={{
          width: `${dims.orbPx}px`,
          height: `${dims.orbPx}px`,
        }}
      >
        {/* Layer 1: Inner Smoked-Glass Domed Disc (underneath canvas edge sheen) */}
        <span
          aria-hidden="true"
          className={cn(
            "pointer-events-none relative z-0 rounded-full border",
            innerDiscClasses
          )}
          style={{
            width: `${innerDiscSize}px`,
            height: `${innerDiscSize}px`,
          }}
        />

        {/* Layer 2: 60fps HiDPI Optical Liquid-Prism Canvas */}
        <span className="pointer-events-none absolute inset-0 z-10">
          <LiquidPrismCanvas
            orbPx={dims.orbPx}
            ringThickness={dims.ringThickness}
            orbitDuration={safeDuration}
            glowIntensity={safeGlow}
            shouldAnimate={shouldAnimate}
            isHovered={isHovered}
          />
        </span>

        {/* Layer 3: Crisp Brushed-Silver Home Icon (above canvas so it stays sharp) */}
        <span className="pointer-events-none absolute inset-0 z-20 flex items-center justify-center">
          {icon ? (
            <span
              className={cn(
                "flex items-center justify-center",
                isDarkOnly
                  ? "text-white"
                  : isLightOnly
                    ? "text-slate-900"
                    : "text-slate-900 dark:text-white",
                dims.iconBox
              )}
            >
              {icon}
            </span>
          ) : (
            <DefaultHomeGlyph
              uid={uid}
              isDarkOnly={isDarkOnly}
              isLightOnly={isLightOnly}
              className={dims.iconBox}
            />
          )}
        </span>
      </span>

      {/* Label Text */}
      {label ? (
        <span
          className={cn(
            "relative z-10 font-normal leading-none transition-colors duration-200",
            dims.label,
            labelColorClasses
          )}
        >
          {label}
        </span>
      ) : null}
    </motion.button>
  );
});

